mapper.select:

		/*iljin_getCod2*/
        	SELECT	
        		CODE	
        		, TEXT1	
        	FROM ICOMCOD2	
        	WHERE 1=1	
        		AND COMPANY_CODE = #{st_buyer} 
        		AND TYPE =  #{st_type} 	
				AND FLAG = 'Y'	
        	ORDER BY TEXT1


/*common.mpso.iljin_item_info*/
	SELECT NVL( MAX(TEXT3) , 'N') AS INVENTORY_FLAG, COUNT(*) AS ORG_CNT
	  FROM ICOMCOD3
	 WHERE BUYER = #{st_buyer}
	   AND TYPE = 'C028'
	   AND TEXT1 = #{st_item_no}

/*common.mpso.iljin_org_list*/
SELECT
	   COD2.TYPE,
	   COD2.CODE,
	   '(' || COD2.TEXT1 || ')' || COD2.TEXT2 AS TEXT1
  FROM ICOMCOD2 COD2
 WHERE COMPANY_CODE = #{SEARCH1}
   AND COD2.TYPE    = #{SEARCH2}
   AND COD2.FLAG    = 'Y'
   AND COD2.TEXT1 LIKE 'IJ%'


/*common.mpso.iljin_project_list*/
	SELECT
	 COD2.CODE
	 ,COD2.TEXT1
	 ,COD2.TEXT2
	FROM ICOMCOD2 COD2
	WHERE  COMPANY_CODE = #{st_buyer}
	AND TYPE = #{st_type}
	AND FLAG = 'Y'


	AND COD2.CODE = #{st_code}


	AND UPPER(COD2.TEXT1) LIKE UPPER('%'||#{st_text}||'%')


	AND UPPER(COD2.TEXT4) LIKE UPPER('%'||#{st_text4}||'%')
